import { execFile } from 'node:child_process';
import { mkdtemp, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const CLI = process.argv[2];
const PAIRS = Number(process.argv[3] ?? 12);
const ROUNDS = Number(process.argv[4] ?? 5);

async function makeSession() {
  const repoDir = await mkdtemp(path.join(os.tmpdir(), 'repro-race-'));
  await execFileAsync('git', ['init'], { cwd: repoDir });
  await execFileAsync('git', ['config', 'user.email', 'r@e.com'], { cwd: repoDir });
  await execFileAsync('git', ['config', 'user.name', 'R'], { cwd: repoDir });
  await writeFile(path.join(repoDir, 'README.md'), '# repro\n', 'utf8');
  await execFileAsync('git', ['add', 'README.md'], { cwd: repoDir });
  await execFileAsync('git', ['commit', '-m', 'base'], { cwd: repoDir });
  await execFileAsync('git', ['branch', '-M', 'issue-69/pre-pr-local-iteration'], { cwd: repoDir });
  const started = JSON.parse(
    (await execFileAsync(process.execPath, [CLI, 'session', 'start', 'Race', '--goal', 'g', '--json'], { cwd: repoDir }))
      .stdout,
  );
  await execFileAsync('git', ['add', '.threadloop/config.json'], { cwd: repoDir });
  await execFileAsync('git', ['commit', '-m', 'init'], { cwd: repoDir });
  return { repoDir, sessionId: started.data.session_id };
}

function args(sessionId, key) {
  return ['session','transition','framed','--session',sessionId,'--expected-state-version','0',
    '--idempotency-key',key,'--actor','agent','--input','{}','--json'];
}

const outcomes = new Map();
let races = 0;

async function oneRace() {
  const { repoDir, sessionId } = await makeSession();
  const run = (key) =>
    execFileAsync(process.execPath, [CLI, ...args(sessionId, key)], { cwd: repoDir, maxBuffer: 10 * 1024 * 1024 });
  const results = await Promise.allSettled([run('race-left:0'), run('race-right:0')]);
  races += 1;
  const winners = results.filter((r) => r.status === 'fulfilled').length;
  const rejected = results.find((r) => r.status === 'rejected');
  let code = 'NONE';
  let message = '';
  if (rejected) {
    try {
      const envelope = JSON.parse(rejected.reason.stderr);
      code = envelope.error.code;
      message = envelope.error.message ?? '';
    } catch {
      code = 'UNPARSEABLE';
      message = String(rejected.reason.stderr).slice(0, 200);
    }
  }
  const key = `winners=${winners} loser=${code}`;
  const seen = outcomes.get(key) ?? { count: 0, message };
  outcomes.set(key, { count: seen.count + 1, message: seen.message || message });
}

for (let round = 0; round < ROUNDS; round += 1) {
  await Promise.all(Array.from({ length: PAIRS }, () => oneRace()));
  process.stdout.write(`round ${round + 1}/${ROUNDS} done (${races} races)\n`);
}

console.log(`\n=== ${races} races, ${PAIRS} concurrent pairs ===`);
for (const [key, value] of [...outcomes].sort((a, b) => b[1].count - a[1].count)) {
  console.log(`${String(value.count).padStart(4)}  ${key}`);
  if (value.message) console.log(`      message: ${value.message.slice(0, 220)}`);
}

