// Races two transitions from the same state version. When the loser reports
// STATE_CORRUPTED, dumps the persisted rows to decide between:
//   (a) the database is genuinely inconsistent  -> atomicity bug
//   (b) it re-reads consistent                  -> read-isolation bug
import { execFile } from 'node:child_process';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import os from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const CLI = process.env.CLI;
const PAIRS = Number(process.argv[2] ?? 12);
const ROUNDS = Number(process.argv[3] ?? 20);

async function makeSession() {
  const repoDir = await mkdtemp(path.join(os.tmpdir(), 'diag-race-'));
  await execFileAsync('git', ['init'], { cwd: repoDir });
  await execFileAsync('git', ['config', 'user.email', 'r@e.com'], { cwd: repoDir });
  await execFileAsync('git', ['config', 'user.name', 'R'], { cwd: repoDir });
  await writeFile(path.join(repoDir, 'README.md'), '# diag\n', 'utf8');
  await execFileAsync('git', ['add', 'README.md'], { cwd: repoDir });
  await execFileAsync('git', ['commit', '-m', 'base'], { cwd: repoDir });
  await execFileAsync('git', ['branch', '-M', 'issue-71/race'], { cwd: repoDir });
  const started = JSON.parse(
    (await execFileAsync(process.execPath, [CLI, 'session', 'start', 'Race', '--goal', 'g', '--json'], { cwd: repoDir }))
      .stdout,
  );
  await execFileAsync('git', ['add', '.threadloop/config.json'], { cwd: repoDir });
  await execFileAsync('git', ['commit', '-m', 'init'], { cwd: repoDir });
  return { repoDir, sessionId: started.data.session_id };
}

function transitionArgs(sessionId, key) {
  return ['session','transition','framed','--session',sessionId,'--expected-state-version','0',
    '--idempotency-key',key,'--actor','agent','--input','{}','--json'];
}

function dump(repoDir, sessionId) {
  const db = new DatabaseSync(path.join(repoDir, '.threadloop/state/state.db'), { readOnly: true });
  try {
    const transitions = db
      .prepare(`SELECT id, from_state, to_state, from_state_version, to_state_version
                FROM session_transitions WHERE session_id = ? ORDER BY rowid`)
      .all(sessionId);
    const task = db
      .prepare(`SELECT t.id, t.status, t.state_version FROM tasks t
                JOIN sessions s ON s.task_id = t.id WHERE s.id = ?`)
      .get(sessionId);
    const audit = db
      .prepare(`SELECT COUNT(*) AS n FROM audit_events WHERE session_id = ?`)
      .get(sessionId);
    const applied = db
      .prepare(`SELECT COUNT(*) AS n FROM audit_events WHERE session_id = ? AND event_type = 'transition_applied'`)
      .get(sessionId);
    return { transitions, task, auditTotal: audit?.n, auditApplied: applied?.n };
  } finally {
    db.close();
  }
}

let corrupted = 0;
let races = 0;
const findings = [];

async function oneRace() {
  const { repoDir, sessionId } = await makeSession();
  const run = (key) =>
    execFileAsync(process.execPath, [CLI, ...transitionArgs(sessionId, key)], { cwd: repoDir, maxBuffer: 10 ** 7 });
  const results = await Promise.allSettled([run('race-left:0'), run('race-right:0')]);
  races += 1;
  const rejected = results.find((r) => r.status === 'rejected');
  if (!rejected) return;
  let envelope;
  try {
    envelope = JSON.parse(rejected.reason.stderr);
  } catch {
    return;
  }
  if (envelope.error?.code !== 'STATE_CORRUPTED') return;
  corrupted += 1;
  findings.push({
    message: envelope.error.message,
    details: envelope.error.details ?? null,
    persisted: dump(repoDir, sessionId),
    fulfilled: results.filter((r) => r.status === 'fulfilled').length,
  });
}

for (let round = 0; round < ROUNDS; round += 1) {
  await Promise.all(Array.from({ length: PAIRS }, () => oneRace()));
}

console.log(`\n${races} races, ${corrupted} STATE_CORRUPTED\n`);
for (const f of findings) {
  console.log('message:  ', f.message);
  console.log('details:  ', JSON.stringify(f.details));
  console.log('winners:  ', f.fulfilled);
  console.log('persisted:', JSON.stringify(f.persisted, null, 2));
  console.log('---');
}

